<?php
declare(strict_types=1);
function h(mixed $value): string {return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function admin_assets(): void {
    $root=rtrim($_SERVER['DOCUMENT_ROOT'],'/');
    foreach(new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root.'/_next/static',FilesystemIterator::SKIP_DOTS)) as $file)if($file->getExtension()==='css')echo '<link rel="stylesheet" href="'.h(substr($file->getPathname(),strlen($root))).'">';
}
function admin_head(string $title): void {
    header('Content-Type: text/html; charset=UTF-8');header("Content-Security-Policy: default-src 'none'; style-src 'self'; font-src 'self'; script-src 'self'; form-action 'self'; base-uri 'none'; frame-ancestors 'none'");
    echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>'.h($title).' | Baran&#39;s Scoreboard</title><link rel="icon" href="/icon.png"><script src="/theme.js"></script><script src="/admin-theme.js" defer></script>';admin_assets();echo '</head><body class="bg-paper text-ink">';
}
function admin_table(array $rows): void {
    if(!$rows){echo '<p class="py-4 text-base text-forest/90">No consented records in this period.</p>';return;}
    echo '<div class="overflow-x-auto"><table class="w-full text-left text-base"><thead><tr>';
    foreach(array_keys($rows[0]) as $key)echo '<th scope="col" class="border-b border-forest/25 px-3 py-3 font-semibold">'.h(ucfirst(str_replace('_',' ',$key))).'</th>';
    echo '</tr></thead><tbody>';foreach($rows as $row){echo '<tr>';foreach($row as $cell)echo '<td class="border-b border-forest/10 px-3 py-3 tabular-nums">'.h(is_string($cell)?european_date($cell):$cell).'</td>';echo '</tr>';}
    echo '</tbody></table></div>';
}
function admin_page(PDO $db,array $c): never {
    start_admin_session($c);$error='';
    $views=['overview'=>'Overview','activity'=>'Activity','pages'=>'Pages & languages','clicks'=>'Button clicks','privacy'=>'Privacy Policy','settings'=>'Settings'];
    $view=$_GET['view']??'overview';if(!is_string($view)||!isset($views[$view]))fail(404);
    $language=$_GET['language']??'bg';if(!in_array($language,['bg','tr','en'],true))fail(400);
    if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
        if((int)($_SERVER['CONTENT_LENGTH']??0)>524288)fail(413);
        same_origin($c);csrf();$action=$_POST['action']??'';
        if($action==='login'){
            $limited=!request_rate_limit($db,$c,'admin-login',5);$password=$_POST['password']??'';$username=$_POST['username']??'';
            $validPassword=!$limited&&is_string($password)&&strlen($password)<=1024&&$c['admin_hash']!==''&&password_verify($password,$c['admin_hash']);
            $validUsername=is_string($username)&&strlen($username)<=100&&$c['admin_username']!==''&&hash_equals($c['admin_username'],$username);
            if($limited){http_response_code(429);$error='Too many attempts. Try again after 15 minutes.';}
            elseif($validPassword&&$validUsername){session_regenerate_id(true);$_SESSION=['admin'=>true,'expires'=>time()+3600,'csrf'=>bin2hex(random_bytes(32)),'auth_version'=>hash_hmac('sha256',$c['admin_username']."\0".$c['admin_hash'],$c['key'])];header('Location: /admin',true,303);exit;}
            else{http_response_code(401);$error='Sign-in failed. Check your username and password.';}
        }else{
            if(!authorized())fail(401);
            if($action==='logout'){$_SESSION=[];session_destroy();setcookie('score_admin','',['expires'=>1,'path'=>'/','secure'=>$c['secure_cookies'],'httponly'=>true,'samesite'=>'Strict']);header('Location: /admin',true,303);exit;}
            if($action==='save_policy'||$action==='restore_policy'){
                $lang=$_POST['language']??'';$revision=filter_var($_POST['revision']??'',FILTER_VALIDATE_INT);
                if(!in_array($lang,['bg','tr','en'],true)||$revision===false)fail(400);
                if($action==='restore_policy'){
                    $previous=filter_var($_POST['previous']??'',FILTER_VALIDATE_INT);if($previous===false||$previous<0)fail(400);
                    $file=$c['policy_path'].'/history/'.$lang.'-'.str_pad((string)$previous,8,'0',STR_PAD_LEFT).'.json';if(!is_file($file))fail(404);$p=json_decode(file_get_contents($file),true,16,JSON_THROW_ON_ERROR);$title=$p['title'];$content=$p['content'];
                }else{$title=$_POST['title']??'';$content=$_POST['content']??'';if(!is_string($title)||!is_string($content))fail(400);}
                save_policy($c,$lang,trim($title),trim($content),(int)$revision);$_SESSION['notice']='Privacy Policy published. Only the selected language was changed.';header('Location: /admin?view=privacy&language='.$lang,true,303);exit;
            }else fail(400);
            fail(400);
        }
    }
    $csrf='<input type="hidden" name="csrf" value="'.h($_SESSION['csrf']).'">';
    if(!authorized()){
        admin_head('Administrator sign-in');?><main class="mx-auto flex min-h-dvh w-full max-w-md flex-col justify-center px-6 py-10"><a href="/bg/" class="mb-8 inline-flex min-h-11 items-center text-base font-medium text-forest hover:underline">← Back to the scoreboard</a><h1 class="mb-6 font-display text-3xl font-bold tracking-tight">Sign in</h1><?php if($error):?><p role="alert" class="mb-4 rounded-lg border border-red-300 p-3 text-base text-red-800 dark:text-red-200"><?=h($error)?></p><?php endif;?><form method="post" action="/admin" class="grid gap-4"><?=$csrf?><input type="hidden" name="action" value="login"><label class="grid gap-2 text-base font-medium">Username<input name="username" required maxlength="100" autocomplete="username" autocapitalize="none" spellcheck="false" class="min-h-12 rounded-lg border border-forest/25 bg-surface px-3"></label><label class="grid gap-2 text-base font-medium">Password<input type="password" name="password" required maxlength="1024" autocomplete="current-password" class="min-h-12 rounded-lg border border-forest/25 bg-surface px-3"></label><button class="mt-2 min-h-12 rounded-lg bg-action px-5 text-base font-semibold text-on-action transition-opacity duration-150 hover:opacity-90 motion-reduce:transition-none">Sign in</button></form></main></body></html><?php exit;
    }
    $notice=$_SESSION['notice']??'';unset($_SESSION['notice']);
    $from=$_GET['from']??gmdate('Y-m-d',time()-29*86400);$to=$_GET['to']??gmdate('Y-m-d');
    $from=normalise_date($from);$to=normalise_date($to);
    if($from>$to||strtotime($to)-strtotime($from)>366*86400)fail(400);
    $period=$_GET['period']??'day';if(!is_string($period)||!in_array($period,['day','week','month'],true))fail(400);
    admin_head($views[$view]);
    $start=$from.' 00:00:00';$end=gmdate('Y-m-d',strtotime($to.' UTC')+86400).' 00:00:00';
    $query=static function(string $sql,array $args=[])use($db):array{$q=$db->prepare($sql);$q->execute($args);return $q->fetchAll(PDO::FETCH_ASSOC);};
    $nav=static function()use($views,$view):void{foreach($views as $key=>$label)echo '<a href="/admin?view='.h($key).'" '.($view===$key?'aria-current="page" ':'').'class="flex min-h-11 items-center rounded-lg px-3 py-2 text-base font-medium transition-colors duration-150 motion-reduce:transition-none '.($view===$key?'bg-action text-on-action':'hover:bg-forest/8').'">'.h($label).'</a>';};
    ?><div class="min-h-dvh md:grid md:grid-cols-[15rem_minmax(0,1fr)]"><aside class="border-b border-forest/15 bg-surface px-4 py-4 md:flex md:min-h-dvh md:flex-col md:border-b-0 md:border-r md:p-5"><a href="/bg/" class="mb-3 inline-flex min-h-11 items-center text-base font-medium text-forest hover:underline">← Scoreboard</a><p class="mb-4 font-display text-2xl font-bold">Administration</p><nav aria-label="Administration" class="hidden gap-1 md:flex md:flex-col"><?php $nav();?></nav><details class="md:hidden"><summary class="min-h-11 cursor-pointer py-2 font-semibold">Menu</summary><nav aria-label="Administration" class="grid gap-1"><?php $nav();?></nav></details><div class="mt-5 flex flex-wrap gap-2 md:mt-auto md:pt-6"><button type="button" id="admin-theme" aria-label="Switch light or dark theme" class="min-h-11 rounded-lg border border-forest/25 px-3 text-base">Light / Dark</button><form method="post" action="/admin"><?=$csrf?><button name="action" value="logout" class="min-h-11 rounded-lg border border-forest/25 px-3 text-base">Sign out</button></form></div></aside><main class="min-w-0 px-5 py-6 md:px-8"><div class="mx-auto max-w-6xl"><h1 class="font-display text-3xl font-bold tracking-tight"><?=h($views[$view])?></h1><?php if($c['http']):?><p class="mt-2 text-base text-forest/90">Local HTTP preview. No production data.</p><?php endif;?><?php if($notice):?><p role="status" class="mt-4 rounded-lg bg-forest/8 px-4 py-3 text-base"><?=h($notice)?></p><?php endif;?>
    <?php if(in_array($view,['overview','activity','pages','clicks'],true)):?>
    <p class="mt-3 max-w-3xl text-base leading-7 text-forest/90">Only visitors who opted in are counted. Your visits are not counted while you are signed in as an administrator. Times are UTC; active time is an estimate.</p><form method="get" action="/admin" class="my-5 flex flex-wrap items-end gap-3"><input type="hidden" name="view" value="<?=h($view)?>"><label class="grid gap-2 text-base">From<input type="text" inputmode="numeric" name="from" required placeholder="DD.MM.YYYY" pattern="[0-9]{2}\.[0-9]{2}\.[0-9]{4}" value="<?=h(european_date($from))?>" class="min-h-11 rounded-lg border border-forest/25 bg-surface px-3"></label><label class="grid gap-2 text-base">To<input type="text" inputmode="numeric" name="to" required placeholder="DD.MM.YYYY" pattern="[0-9]{2}\.[0-9]{2}\.[0-9]{4}" value="<?=h(european_date($to))?>" class="min-h-11 rounded-lg border border-forest/25 bg-surface px-3"></label><button class="min-h-11 rounded-lg bg-action px-5 text-base font-semibold text-on-action">Apply</button></form>
    <?php endif;
    if($view==='overview'){
        $v=$query('SELECT COUNT(*) AS n,COALESCE(SUM(active_seconds),0) AS seconds FROM visits WHERE started_at >= ? AND started_at < ? AND started_at > UTC_TIMESTAMP() - INTERVAL 365 DAY',[$start,$end])[0];$pages=$query('SELECT COUNT(*) AS n FROM pageviews WHERE occurred_at >= ? AND occurred_at < ? AND occurred_at > UTC_TIMESTAMP() - INTERVAL 365 DAY',[$start,$end])[0]['n'];
        echo '<dl class="grid gap-3 sm:grid-cols-3">';foreach(['Recorded visits'=>$v['n'],'Page views'=>$pages,'Active minutes'=>round((int)$v['seconds']/60)] as $label=>$number)echo '<div class="rounded-xl border border-forest/20 bg-surface p-5"><dt class="text-base">'.h($label).'</dt><dd class="mt-2 font-display text-4xl font-bold tabular-nums text-forest">'.h($number).'</dd></div>';echo '</dl><h2 class="mt-7 mb-3 font-display text-xl font-bold">Recent daily activity</h2>';
        admin_table($query('SELECT DATE(started_at) AS day,COUNT(*) AS visits FROM visits WHERE started_at >= ? AND started_at < ? AND started_at > UTC_TIMESTAMP() - INTERVAL 365 DAY GROUP BY day ORDER BY day DESC LIMIT 14',[$start,$end]));
    }elseif($view==='activity'){
        $period=$_GET['period']??'day';$periods=['day'=>['DATE(started_at)','Daily'],'week'=>['YEARWEEK(started_at,3)','Weekly'],'month'=>["DATE_FORMAT(started_at,'%Y-%m')",'Monthly']];if(!is_string($period)||!isset($periods[$period]))fail(400);
        echo '<nav aria-label="Activity grouping" class="mb-4 flex flex-wrap gap-2">';foreach($periods as $key=>$details)echo '<a class="min-h-11 rounded-lg border border-forest/25 px-4 py-2 text-base" href="/admin?view=activity&amp;period='.h($key).'&amp;from='.h($from).'&amp;to='.h($to).'">'.h($details[1]).'</a>';echo '</nav>';
        admin_table($query('SELECT '.$periods[$period][0].' AS period,COUNT(*) AS visits,SUM(active_seconds) AS active_seconds FROM visits WHERE started_at >= ? AND started_at < ? AND started_at > UTC_TIMESTAMP() - INTERVAL 365 DAY GROUP BY period ORDER BY period DESC',[$start,$end]));
    }elseif($view==='pages'){
        echo '<h2 class="mb-3 font-display text-xl font-bold">Public pages</h2>';admin_table($query('SELECT path,COUNT(*) AS views FROM pageviews WHERE occurred_at >= ? AND occurred_at < ? AND occurred_at > UTC_TIMESTAMP() - INTERVAL 365 DAY GROUP BY path ORDER BY views DESC',[$start,$end]));echo '<h2 class="mt-7 mb-3 font-display text-xl font-bold">Languages</h2>';admin_table($query('SELECT SUBSTRING(path,2,2) AS language,COUNT(*) AS views FROM pageviews WHERE occurred_at >= ? AND occurred_at < ? AND occurred_at > UTC_TIMESTAMP() - INTERVAL 365 DAY GROUP BY language ORDER BY views DESC',[$start,$end]));
    }elseif($view==='clicks'){
        admin_table($query('SELECT label,COUNT(*) AS clicks FROM events WHERE occurred_at >= ? AND occurred_at < ? AND occurred_at > UTC_TIMESTAMP() - INTERVAL 365 DAY GROUP BY label ORDER BY clicks DESC',[$start,$end]));
    }elseif($view==='privacy'){
        $p=policy_document($c,$language);?><p class="my-4 max-w-3xl text-base leading-7">Edit one language at a time. Publishing changes the public policy immediately. Use blank lines between paragraphs and start section headings with ##.</p><nav aria-label="Policy language" class="mb-5 flex gap-2"><?php foreach(['bg'=>'Български','tr'=>'Türkçe','en'=>'English'] as $code=>$label):?><a href="/admin?view=privacy&amp;language=<?=h($code)?>" class="min-h-11 rounded-lg border border-forest/25 px-4 py-2 text-base <?= $code===$language?'bg-action text-on-action':''?>"><?=h($label)?></a><?php endforeach;?></nav><form method="post" action="/admin?view=privacy&amp;language=<?=h($language)?>" class="grid gap-4"><?=$csrf?><input type="hidden" name="action" value="save_policy"><input type="hidden" name="language" value="<?=h($language)?>"><input type="hidden" name="revision" value="<?=h($p['revision'])?>"><label class="grid gap-2 text-base font-medium">Title<input name="title" required maxlength="200" value="<?=h($p['title'])?>" class="min-h-12 rounded-lg border border-forest/25 bg-surface px-3"></label><label class="grid gap-2 text-base font-medium">Policy text<textarea name="content" required minlength="50" maxlength="100000" rows="18" class="w-full rounded-lg border border-forest/25 bg-surface p-3 text-base leading-7"><?=h($p['content'])?></textarea></label><div class="flex flex-wrap items-center gap-3"><button class="min-h-12 rounded-lg bg-action px-5 text-base font-semibold text-on-action">Publish changes</button><a href="<?=h(policy_paths()[$language])?>" target="_blank" rel="noopener noreferrer" class="inline-flex min-h-11 items-center px-3 text-base font-medium underline underline-offset-4">View public policy</a></div></form><?php
        $history=glob($c['policy_path'].'/history/'.$language.'-*.json')?:[];rsort($history);if($history){?><details class="mt-6"><summary class="min-h-11 cursor-pointer py-2 font-semibold">Previous versions</summary><form method="post" action="/admin?view=privacy&amp;language=<?=h($language)?>" class="mt-3 flex flex-wrap gap-3"><?=$csrf?><input type="hidden" name="action" value="restore_policy"><input type="hidden" name="language" value="<?=h($language)?>"><input type="hidden" name="revision" value="<?=h($p['revision'])?>"><label class="grid gap-2 text-base">Version<select name="previous" class="min-h-11 rounded-lg border border-forest/25 bg-surface px-3"><?php foreach($history as $file){$old=json_decode(file_get_contents($file),true);echo '<option value="'.h($old['revision']).'">'.h(european_date(str_replace('T',' ',substr($old['updatedAt'],0,16)))).' — revision '.h($old['revision']).'</option>';}?></select></label><button name="action" value="restore_policy" class="min-h-11 self-end rounded-lg border border-forest/25 px-4 text-base">Restore selected version</button></form></details><?php }
    }else{?>
    <p class="my-4 max-w-3xl text-base leading-7">These deployment settings are configured in the private environment file, outside the public website. No credentials or secret values are shown here.</p><dl class="max-w-3xl divide-y divide-forest/15"><?php foreach(['Site origin'=>$c['origin'],'Administrator route'=>'/admin','Site usage analytics'=>$c['analytics']?'Enabled — visitor consent still required':'Disabled','Cloudflare Web Analytics'=>capabilities($c)['cloud']?'Configured — separate visitor consent required':'Disabled','Session lifetime'=>'1 hour','Analytics retention'=>'At most 365 days','Security rate-limit retention'=>'15 minutes','Automatic cleanup'=>'Schedule hourly with the host scheduler or Docker cleanup service','Privacy Policy'=>'Editable here; published versions survive application updates'] as $key=>$value):?><div class="grid gap-2 py-4 sm:grid-cols-2"><dt class="font-semibold"><?=h($key)?></dt><dd class="break-words text-base"><?=h($value)?></dd></div><?php endforeach;?></dl>
    <?php }?></div></main></div></body></html><?php exit;
}
